from pathlib import Path
p=Path('/mnt/data/bgwork/index.html')
s=p.read_text()
old="$('profileBtn').onclick=()=>{let p=profile||{};modal(`<h3>👤 Мой профиль</h3><div class=\"stack\"><label>Имя<input id=\"editName\" maxlength=\"40\" value=\"${safe(p.name||currentUser.displayName||'')}\"></label><label>О себе / статус<input id=\"editStatus\" maxlength=\"80\" value=\"${safe(p.status||'')}\"></label><label>Ссылка на аватар (HTTPS)<input id=\"editAvatar\" value=\"${safe(p.photoURL||'')}\" placeholder=\"https://...\"></label><button id=\"saveProfile\">Сохранить профиль</button></div>`);$('saveProfile').onclick=async()=>{let name=$('editName').value.trim(),status=$('editStatus').value.trim(),photoURL=$('editAvatar').value.trim();if(name.length<2)return alert('Имя должно быть не короче 2 символов');if(photoURL&&!/^https:\/\//i.test(photoURL))return alert('Ссылка на аватар должна начинаться с https://');try{await setDoc(doc(db,'users',currentUser.uid),{name,status,photoURL},{merge:true});await updateProfile(currentUser,{displayName:name,photoURL:photoURL||null});profile={...profile,name,status,photoURL};$('me').textContent='Ты: '+name+(status?' · '+status:'');closeModal();renderPeople()}catch(e){alert('Не удалось сохранить профиль: '+e.message)}}};"
if old not in s:
    print('old handler not found')
else:
    s=s.replace(old,"$('profileBtn').onclick=()=>bg5OpenProfile(profile||{},true);")
css='''\n/* Blackgram 5.2 profile layout */\n.profile-page{margin:-18px;overflow:hidden;background:var(--bg);border-radius:20px}.profile-cover{padding:30px 18px 18px;text-align:center;background:linear-gradient(145deg,#536474,#354657 65%,#263746);position:relative}.profile-cover .profile-avatar{width:104px;height:104px;border-radius:50%;object-fit:cover;border:3px solid #ffffff35;background:#17212b;display:block;margin:0 auto 12px}.profile-cover h2{font-size:21px;margin:0 0 5px}.profile-presence{font-size:12px;color:#e0e8ef}.profile-actions{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;padding:12px;background:var(--panel)}.profile-actions button{padding:10px 3px;font-size:12px;background:#304355;border:0}.profile-music{text-align:center;font-size:12px;padding:0 12px 12px;color:#d9e7f5}.profile-body{padding:12px;display:grid;gap:10px}.profile-card{background:var(--panel);border-radius:16px;padding:14px}.profile-channel{display:flex;align-items:center;gap:10px}.profile-channel img{width:54px;height:54px;border-radius:12px;object-fit:cover}.profile-field{padding:9px 0;border-bottom:1px solid var(--line);overflow-wrap:anywhere}.profile-field:last-child{border:0}.profile-field small{display:block;color:var(--muted);font-size:11px;margin-top:3px}.profile-add{width:100%;background:var(--panel);color:var(--text);border:0;text-align:left}.profile-tabs{display:flex;gap:5px;overflow:auto;padding:8px 12px;background:var(--panel)}.profile-tabs button{white-space:nowrap;background:var(--panel2);font-size:12px;padding:8px 11px}.profile-tabs button.active{outline:2px solid #68b9ff}.profile-edit-grid{display:grid;gap:10px}.profile-edit-grid label{display:grid;gap:5px;font-size:12px;color:var(--muted)}.profile-edit-grid input,.profile-edit-grid textarea{width:100%;padding:11px;border-radius:11px;border:1px solid var(--line);background:var(--bg);color:var(--text)}.profile-modal .modalbox{padding:18px 18px 14px}@media(max-width:700px){.profile-page{margin:-18px}.profile-cover{padding-top:24px}.profile-actions button{font-size:11px}.profile-body{padding:10px}}\n'''
s=s.replace('</style>',css+'</style>',1)
# Insert function before existing bg5 catalog area, after bg5NeedUser helper
needle="function bg5NeedUser(){if(!currentUser){alert('Сначала войди в Blackgram');return false}return true}"
func=r'''\nfunction bg5OpenProfile(u={},own=false){
 if(!currentUser)return;const p=u||{},name=p.name||p.displayName||'Пользователь',photo=p.photoURL||'',status=p.status||'в сети',username=p.username?'@'+p.username:'Не указан',about=p.about||p.bio||'',birthday=p.birthday||'',address=p.address||'',hours=p.hours||'не указано',music=p.music||'',channel=own?chatCache.find(c=>c.kind==='channel'&&(c.ownerId===currentUser.uid||(c.participants||[]).includes(currentUser.uid))):null;
 const avatar=photo?`<img class="profile-avatar" src="${safe(photo)}" alt="Аватар">`:`<div class="profile-avatar" style="display:grid;place-items:center;font-size:42px">👤</div>`;
 modal(`<div class="profile-page"><div class="profile-cover">${avatar}<h2>${safe(name)} ${userBadges({...p,email:own?currentUser.email:p.email})}</h2><div class="profile-presence">● ${safe(status)}</div></div><div class="profile-actions"><button type="button" data-paction="chat">💬<br>Чат</button><button type="button" data-paction="sound">🔔<br>Звук</button><button type="button" data-paction="call">📞<br>Звонок</button><button type="button" data-paction="gift">🎁<br>Подарок</button></div>${music?`<div class="profile-music">♫ ${safe(music)}</div>`:''}<div class="profile-body">${channel?`<div class="profile-card"><b>Канал</b><div class="profile-channel"><div style="font-size:28px">📢</div><div><b>${safe(channel.title||'Мой канал')}</b><small class="muted" style="display:block">Blackgram</small></div></div></div>`:''}<div class="profile-card">${about?`<div class="profile-field">${safe(about)}<small>О себе</small></div>`:''}<div class="profile-field">${safe(username)}<small>Имя пользователя</small></div>${birthday?`<div class="profile-field">${safe(birthday)}<small>День рождения</small></div>`:''}<div class="profile-field">${safe(hours)}<small>Часы работы</small></div>${address?`<div class="profile-field">${safe(address)}<small>Адрес</small></div>`:''}</div>${own?`<button class="profile-add" id="profileEditOpen">✎　Изменить профиль</button>`:`<button class="profile-add" id="profileAddContact">♙　Добавить в контакты</button>`}</div><div class="profile-tabs"><button class="active" data-ptab="Медиа">Медиа</button><button data-ptab="Ссылки">Ссылки</button><button data-ptab="Музыка">Музыка</button><button data-ptab="Голосовые">Голосовые</button><button data-ptab="Подарки">Подарки 🎁</button></div><div id="profileTabContent" class="profile-body"><div class="profile-card muted">Здесь будут отображаться материалы профиля</div></div></div>`);
 document.querySelectorAll('[data-ptab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-ptab]').forEach(x=>x.classList.toggle('active',x===b));$('profileTabContent').innerHTML=`<div class="profile-card muted">${safe(b.dataset.ptab)} пока пусто</div>`});
 document.querySelectorAll('[data-paction]').forEach(b=>b.onclick=()=>{const a=b.dataset.paction;if(a==='chat'){if(own){closeModal();return}const target=allUsers.find(x=>x.id===p.id);if(target){closeModal();openChat(target)}else alert('Пользователь пока недоступен для чата')}else if(a==='call'){if(!own&&p.id){const target=allUsers.find(x=>x.id===p.id);if(target){closeModal();openChat(target);setTimeout(()=>$('callBtn').click(),250)}else alert('Открой личный чат для звонка')}else alert('Нельзя позвонить самому себе')}else if(a==='sound'){alert('Настройки уведомлений этого профиля можно изменить в чате')}else alert('Подарки появятся в следующем обновлении')});
 if(own)$('profileEditOpen').onclick=()=>bg5EditProfile(p);else if($('profileAddContact'))$('profileAddContact').onclick=()=>alert('Пользователь уже доступен в поиске Blackgram');
}
function bg5EditProfile(p={}){modal(`<h3>✎ Редактировать профиль</h3><div class="profile-edit-grid"><label>Имя<input id="editName" maxlength="40" value="${safe(p.name||currentUser.displayName||'')}"></label><label>О себе<textarea id="editAbout" maxlength="300" rows="3">${safe(p.about||p.bio||'')}</textarea></label><label>Статус<input id="editStatus" maxlength="80" value="${safe(p.status||'')}"></label><label>Ссылка на аватар (HTTPS)<input id="editAvatar" value="${safe(p.photoURL||'')}" placeholder="https://..."></label><label>День рождения<input id="editBirthday" maxlength="40" value="${safe(p.birthday||'')}" placeholder="Например, 09 сентября"></label><label>Адрес<input id="editAddress" maxlength="100" value="${safe(p.address||'')}" placeholder="Город, страна"></label><label>Часы работы<input id="editHours" maxlength="60" value="${safe(p.hours||'')}" placeholder="Круглосуточно"></label><label>Музыка<input id="editMusic" maxlength="100" value="${safe(p.music||'')}" placeholder="Исполнитель — песня"></label></div><button id="saveProfile" style="width:100%;margin-top:14px">Сохранить профиль</button>`);$('saveProfile').onclick=async()=>{let name=$('editName').value.trim(),status=$('editStatus').value.trim(),photoURL=$('editAvatar').value.trim(),about=$('editAbout').value.trim(),birthday=$('editBirthday').value.trim(),address=$('editAddress').value.trim(),hours=$('editHours').value.trim(),music=$('editMusic').value.trim();if(name.length<2)return alert('Имя должно быть не короче 2 символов');if(photoURL&&!/^https:\/\//i.test(photoURL))return alert('Ссылка на аватар должна начинаться с https://');try{const patch={name,status,photoURL,about,birthday,address,hours,music};await setDoc(doc(db,'users',currentUser.uid),patch,{merge:true});await updateProfile(currentUser,{displayName:name,photoURL:photoURL||null});profile={...profile,...patch};$('me').innerHTML=(photoURL?`<img class="avatar" src="${safe(photoURL)}" alt="">`:'')+'Ты: '+safe(name)+(status?' · '+safe(status):'');renderPeople();bg5OpenProfile(profile,true)}catch(e){alert('Не удалось сохранить профиль: '+e.message)}}}
'''
# raw string starts literal backslash n fix
func=func.replace('\\n','\n')
s=s.replace(needle,needle+'\n'+func)
# click chat title opens counterpart profile
s=s.replace("$('bg5ChatSettings').onclick=bg5ChatSettings;", "$('bg5ChatSettings').onclick=bg5ChatSettings;$('chatTitle').style.cursor='pointer';$('chatTitle').addEventListener('click',()=>{if(activeChat?.otherId){const u=allUsers.find(x=>x.id===activeChat.otherId);if(u)bg5OpenProfile(u,false)}});")
p.write_text(s)
# Sync mirrored HTML copies
for q in [Path('/mnt/data/bgwork/www/index.html'),Path('/mnt/data/bgwork/public/index.html')]: q.write_text(s)
